class PhpArray:
    def __init__(self, items=None):
        self.data = OrderedDict()
        self.next_index = 0
        if items:
            for k,v in items:
                self.set(k, v)
    def normalize_key(self,k):
        if isinstance(k,bool): return int(k)
        if isinstance(k,float) and k.is_integer(): return int(k)
        if k is None: return ""
        if isinstance(k,str):
            if re.fullmatch(r'-?(0|[1-9][0-9]*)', k):
                try: return int(k)
                except: pass
            return k
        return k
    def append(self,v):
        k = self.next_index
        while k in self.data: k += 1
        self.data[k]=v; self.next_index=k+1
    def set(self,k,v):
        if k is None:
            self.append(v); return
        k=self.normalize_key(k)
        self.data[k]=v
        if isinstance(k,int) and k >= self.next_index: self.next_index=k+1
    def get(self,k, default=None):
        k=self.normalize_key(k)
        return self.data.get(k, default)
    def isset(self,k):
        k=self.normalize_key(k)
        return k in self.data and self.data[k] is not None
    def unset(self,k):
        k=self.normalize_key(k)
        self.data.pop(k, None)
    def items(self): return list(self.data.items())
    def values(self): return list(self.data.values())
    def keys(self): return list(self.data.keys())
    def __len__(self): return len(self.data)
    def is_list(self): return list(self.data.keys()) == list(range(len(self.data)))
    def copy(self): return PhpArray(self.items())

class PhpObject:
    def __init__(self, cls="stdClass"):
        self.cls=cls; self.props=OrderedDict()

class ReturnExc(Exception):
    def __init__(self, value): self.value=value
class ExitExc(Exception):
    def __init__(self, code=0): self.code=code
class PhpFatal(Exception): pass
class PhpParse(Exception): pass

class Token:
    __slots__=('typ','val','line')
    def __init__(self,typ,val,line): self.typ=typ; self.val=val; self.line=line
    def __repr__(self): return f"T({self.typ},{self.val!r},{self.line})"

KEYWORDS = {'if','else','elseif','while','for','foreach','as','function','return','break','continue','true','false','null','and','or','xor','array','echo','print','include','include_once','require','require_once','exit','die','isset','empty','unset','global','static','new','use'}
MULTI = ['===','!==','**=','<<=','>>=','...','==','!=','<=','>=','++','--','+=','-=','*=','/=','%=','.=','&&','||','=>','??','::','->','**','<<','>>']

class Tokenizer:
    def __init__(self, code): self.code=code; self.i=0; self.line=1; self.n=len(code)
    def peek(self,n=0):
        j=self.i+n
        return self.code[j] if j<self.n else ''
    def adv(self):
        ch=self.code[self.i]; self.i+=1
        if ch=='\n': self.line+=1
        return ch
    def skip_ws_comments(self):
        while self.i<self.n:
            ch=self.peek()
            if ch.isspace(): self.adv(); continue
            if ch=='/' and self.peek(1)=='/':
                while self.i<self.n and self.peek()!='\n': self.adv()
                continue
            if ch=='#':
                while self.i<self.n and self.peek()!='\n': self.adv()
                continue
            if ch=='/' and self.peek(1)=='*':
                self.adv(); self.adv()
                while self.i<self.n and not (self.peek()=='*' and self.peek(1)=='/'):
                    self.adv()
                if self.i<self.n: self.adv(); self.adv()
                continue
            break
    def string(self, quote):
        line=self.line; self.adv(); raw=''
        while self.i<self.n:
            ch=self.adv()
            if ch==quote: break
            if ch=='\\' and self.i<self.n:
                nxt=self.adv()
                if quote=='"':
                    mp={'n':'\n','r':'\r','t':'\t','v':'\v','f':'\f','e':'\x1b','\\':'\\','"':'"','$':'$'}
                    raw += mp.get(nxt, '\\'+nxt)
                else:
                    if nxt in ["'",'\\']: raw+=nxt
                    else: raw+='\\'+nxt
            else: raw+=ch
        return Token('STRING_D' if quote=='"' else 'STRING_S', raw, line)
    def number(self):
        line=self.line; s=''
        if self.peek()=='0' and self.peek(1).lower() in ('x','b'):
            s+=self.adv()+self.adv()
            while self.i<self.n and re.match(r'[0-9a-fA-F]', self.peek()): s+=self.adv()
            return Token('NUMBER', s, line)
        while self.i<self.n and (self.peek().isdigit() or self.peek()=='_' or self.peek()=='.' or self.peek().lower()=='e' or (self.peek() in '+-' and s and s[-1].lower()=='e')):
            if self.peek()=='_' : self.adv(); continue
            s+=self.adv()
            if s.count('.')>1: break
        return Token('NUMBER', s, line)
    def ident(self):
        line=self.line; s=''
        while self.i<self.n and re.match(r'[A-Za-z0-9_\\]', self.peek()): s+=self.adv()
        return Token('ID', s, line)
    def variable(self):
        line=self.line; self.adv(); s='$'
        if self.peek()=='{':
            # ${name}; keep simple
            s+=self.adv();
            while self.i<self.n and self.peek()!='}': s+=self.adv()
            if self.peek()=='}': s+=self.adv()
            return Token('VAR', s, line)
        while self.i<self.n and re.match(r'[A-Za-z0-9_]', self.peek()): s+=self.adv()
        return Token('VAR', s, line)
    def tokenize(self):
        out=[]
        while self.i<self.n:
            self.skip_ws_comments()
            if self.i>=self.n: break
            ch=self.peek(); line=self.line
            if ch in ('"',"'"):
                out.append(self.string(ch)); continue
            if ch=='$': out.append(self.variable()); continue
            if ch.isdigit() or (ch=='.' and self.peek(1).isdigit()): out.append(self.number()); continue
            if re.match(r'[A-Za-z_\\]', ch): out.append(self.ident()); continue
            matched=False
            for op in MULTI:
                if self.code.startswith(op,self.i):
                    out.append(Token('OP',op,line)); self.i+=len(op); matched=True; break
            if matched: continue
            out.append(Token('PUNC' if ch in '(){}[];,:' else 'OP', ch, line)); self.adv()
        out.append(Token('EOF','',self.line))
        return out

def tokenize(code): return Tokenizer(code).tokenize()

def php_truth(v):
    if v is None: return False
    if isinstance(v,bool): return v
    if isinstance(v,(int,float)): return v!=0
    if isinstance(v,str): return not (v=='' or v=='0')
    if isinstance(v,PhpArray): return len(v)>0
    return True

def php_string(v):
    if v is None: return ''
    if isinstance(v,bool): return '1' if v else ''
    if isinstance(v,int): return str(v)
    if isinstance(v,float):
        if math.isnan(v): return 'NAN'
        if math.isinf(v): return 'INF' if v>0 else '-INF'
        s=("%.14g" % v)
        return s
    if isinstance(v,str): return v
    if isinstance(v,PhpArray): return 'Array'
    if isinstance(v,PhpObject): return f"Object"
    return str(v)

def php_num(v):
    if v is None: return 0
    if isinstance(v,bool): return 1 if v else 0
    if isinstance(v,(int,float)): return v
    if isinstance(v,str):
        m=re.match(r'^[\s]*([+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?)',v)
        if not m: return 0
        s=m.group(1)
        return float(s) if any(c in s for c in '.eE') else int(s)
    return 1 if php_truth(v) else 0

def php_int(v):
    try: return int(php_num(v))
    except: return 0

def loose_eq(a,b):
    if a is None and b is None: return True
    if isinstance(a,bool) or isinstance(b,bool) or a is None or b is None:
        return php_truth(a)==php_truth(b)
    if isinstance(a,(int,float)) or isinstance(b,(int,float)):
        return php_num(a)==php_num(b)
    if isinstance(a,PhpArray) and isinstance(b,PhpArray): return a.items()==b.items()
    if isinstance(a,PhpArray) or isinstance(b,PhpArray): return False if not (not php_truth(a) and not php_truth(b)) else True
    return php_string(a)==php_string(b)

def strict_eq(a,b):
    if type(a) is not type(b): return False
    if isinstance(a,PhpArray): return a.items()==b.items()
    return a==b

def format_scalar(v):
    if v is None: return ''
    if isinstance(v,bool): return '1' if v else ''
    return php_string(v)

class LValue:
    def __init__(self, interp, base, indexes=None):
        self.interp=interp; self.base=base; self.indexes=indexes or []
    def _container(self, create=False):
        if not self.indexes: return None, None
        v=self.interp.vars.get(self.base)
        if not isinstance(v, PhpArray):
            if create:
                v=PhpArray(); self.interp.vars[self.base]=v
            else: return None, None
        arr=v
        for idx in self.indexes[:-1]:
            key=idx
            nxt=arr.get(key)
            if not isinstance(nxt,PhpArray):
                if create:
                    nxt=PhpArray(); arr.set(key,nxt)
                else: return None,None
            arr=nxt
        return arr, self.indexes[-1]
    def get(self, quiet=False):
        if not self.indexes:
            if self.base in self.interp.vars: return self.interp.vars[self.base]
            if not quiet: self.interp.warning(f"Undefined variable ${self.base}")
            return None
        arr,key=self._container(False)
        if arr is None: return None
        return arr.get(key)
    def isset(self):
        if not self.indexes: return self.base in self.interp.vars and self.interp.vars[self.base] is not None
        arr,key=self._container(False)
        return arr.isset(key) if arr is not None else False
    def set(self,val):
        if not self.indexes:
            self.interp.vars[self.base]=val; return val
        arr,key=self._container(True)
        arr.set(key,val); return val
    def unset(self):
        if not self.indexes: self.interp.vars.pop(self.base,None)
        else:
            arr,key=self._container(False)
            if arr: arr.unset(key)

class ExprParser:
    PRECEDENCE = {
        '??':2, '||':3, 'or':3, '&&':4, 'and':4, 'xor':4,
        '|':5, '^':6, '&':7,
        '==':8,'!=':8,'===':8,'!==':8,'<=>':8,
        '<':9,'>':9,'<=':9,'>=':9,
        '<<':10,'>>':10,
        '+':11,'-':11,'.':11,
        '*':12,'/':12,'%':12,
        '**':14,
    }
    RIGHT={'**','??'}
    def __init__(self, interp, tokens): self.I=interp; self.t=tokens; self.p=0
    def peek(self): return self.t[self.p] if self.p<len(self.t) else Token('EOF','',0)
    def pop(self): tok=self.peek(); self.p+=1; return tok
    def match(self,val):
        if self.peek().val==val: self.p+=1; return True
        return False
    def expect(self,val):
        if not self.match(val): raise PhpParse(f"unexpected token {self.peek().val!r}")
    def parse(self):
        if not self.t or (len(self.t)==1 and self.t[0].typ=='EOF'): return None
        return self.expr(0)
    def expr(self,minp):
        left=self.prefix()
        while True:
            tok=self.peek(); op=tok.val
            if op=='?':
                prec=1
                if prec<minp: break
                self.pop()
                if self.match(':'):
                    if php_truth(left):
                        # PHP elvis: a ?: b returns a
                        right_true=left
                    else:
                        right_true=self.expr(0)
                    left=right_true
                else:
                    mid=self.expr(0); self.expect(':'); right=self.expr(0)
                    left=mid if php_truth(left) else right
                continue
            if op not in self.PRECEDENCE: break
            prec=self.PRECEDENCE[op]
            if prec<minp: break
            self.pop()
            if op in ('&&','and'):
                if not php_truth(left):
                    _=self.expr(prec+(0 if op in self.RIGHT else 1)); left=False
                else: left=php_truth(self.expr(prec+1));
                continue
            if op in ('||','or'):
                if php_truth(left):
                    _=self.expr(prec+1); left=True
                else: left=php_truth(self.expr(prec+1))
                continue
            if op=='??':
                right=self.expr(prec)
                left = left if left is not None else right
                continue
            right=self.expr(prec + (0 if op in self.RIGHT else 1))
            left=self.apply_op(op,left,right)
        return left
    def prefix(self):
        tok=self.pop(); val=tok.val
        if val in ('+','-','!','~'):
            v=self.expr(13)
            if val=='+': return +php_num(v)
            if val=='-': return -php_num(v)
            if val=='!': return not php_truth(v)
            return ~php_int(v)
        if val in ('++','--'):
            lv=self.parse_lvalue_from_token(self.pop())
            cur=lv.get(True); new=php_num(cur)+(1 if val=='++' else -1); new=int(new) if isinstance(new,float) and new.is_integer() else new
            lv.set(new); return new
        if tok.typ=='NUMBER':
            s=val.replace('_','')
            try:
                if s.lower().startswith('0x'): v=int(s,16)
                elif s.lower().startswith('0b'): v=int(s,2)
                elif any(c in s for c in '.eE'): v=float(s)
                else: v=int(s,10)
            except: v=0
            return self.postfix(v)
        if tok.typ in ('STRING_S','STRING_D'):
            v=tok.val if tok.typ=='STRING_S' else self.I.interpolate(tok.val)
            return self.postfix(v)
        if tok.typ=='VAR':
            lv=self.parse_lvalue_from_token(tok)
            v=lv.get(False)
            return self.postfix(v, lv)
        if tok.typ=='ID':
            low=val.lower()
            if low=='true': return True
            if low=='false': return False
            if low=='null': return None
            if low=='array':
                self.expect('('); arr=self.parse_array(')'); return self.postfix(arr)
            if low=='isset':
                self.expect('('); res=True
                first=True
                while not self.match(')'):
                    if not first: self.expect(',')
                    first=False
                    if self.peek().typ=='VAR':
                        lv=self.parse_lvalue_from_token(self.pop(), quiet_index=True); res = res and lv.isset()
                    else:
                        res = res and (self.expr(0) is not None)
                return res
            if low=='empty':
                self.expect('(')
                if self.peek().typ=='VAR': v=self.parse_lvalue_from_token(self.pop(), quiet_index=True).get(True)
                else: v=self.expr(0)
                self.expect(')'); return not php_truth(v)
            if low=='new':
                cls='stdClass'
                if self.peek().typ=='ID': cls=self.pop().val
                if self.match('('): self.skip_balanced(')')
                return PhpObject(cls)
            if self.match('('):
                args=self.parse_args_after_open()
                return self.postfix(self.I.call_function(val,args))
            const=self.I.get_constant(val)
            if const is None:
                raise PhpFatal(f'Undefined constant "{val}"')
            return self.postfix(const)
        if val=='(':
            v=self.expr(0); self.expect(')'); return self.postfix(v)
        if val=='[':
            arr=self.parse_array(']'); return self.postfix(arr)
        raise PhpParse(f"unexpected token {val!r}")
    def postfix(self, v, lv=None):
        while True:
            if self.match('['):
                if self.match(']'): key=None
                else: key=self.expr(0); self.expect(']')
                if isinstance(v, PhpArray): v=v.get(key)
                elif isinstance(v, str):
                    try: v=v[php_int(key)]
                    except: v=''
                else: v=None
                lv=None
                continue
            if self.match('->'):
                prop=self.pop().val if self.peek().typ in ('ID','VAR') else ''
                if isinstance(v,PhpObject):
                    if self.match('('): self.skip_balanced(')'); v=None
                    else: v=v.props.get(prop)
                else: v=None
                continue
            if self.peek().val in ('++','--'):
                op=self.pop().val
                old=v
                if lv is not None:
                    new=php_num(old)+(1 if op=='++' else -1); new=int(new) if isinstance(new,float) and new.is_integer() else new
                    lv.set(new)
                return old
            break
        return v
    def parse_lvalue_from_token(self,tok, quiet_index=False):
        name=tok.val[1:]
        if name.startswith('{') and name.endswith('}'): name=name[1:-1]
        idx=[]
        while self.match('['):
            if self.match(']'): key=None
            else: key=self.expr(0); self.expect(']')
            idx.append(key)
        return LValue(self.I,name,idx)
    def parse_args_after_open(self):
        args=[]
        if self.match(')'): return args
        while True:
            args.append(self.expr(0))
            if self.match(')'): break
            self.expect(',')
        return args
    def parse_array(self,end):
        arr=PhpArray()
        if self.match(end): return arr
        while True:
            if self.match(end): break
            first=self.expr(0)
            if self.match('=>'):
                val=self.expr(0); arr.set(first,val)
            else:
                arr.append(first)
            if self.match(end): break
            self.expect(',')
        return arr
    def skip_balanced(self,end):
        depth=1
        while self.p<len(self.t) and depth>0:
            tok=self.pop()
            if tok.val in ('(','[','{'): depth+=1
            elif tok.val==end: depth-=1
    def apply_op(self,op,a,b):
        try:
            if op=='+':
                if isinstance(a,PhpArray) and isinstance(b,PhpArray):
                    r=a.copy()
                    for k,v in b.items():
                        if k not in r.data: r.set(k,v)
                    return r
                x,y=php_num(a),php_num(b); z=x+y; return int(z) if isinstance(z,float) and z.is_integer() else z
            if op=='-': z=php_num(a)-php_num(b); return int(z) if isinstance(z,float) and z.is_integer() else z
            if op=='*': z=php_num(a)*php_num(b); return int(z) if isinstance(z,float) and z.is_integer() else z
            if op=='/': return php_num(a)/php_num(b)
            if op=='%': return php_int(a)%php_int(b)
            if op=='**': return php_num(a)**php_num(b)
            if op=='.': return php_string(a)+php_string(b)
            if op=='==': return loose_eq(a,b)
            if op=='!=': return not loose_eq(a,b)
            if op=='===': return strict_eq(a,b)
            if op=='!==': return not strict_eq(a,b)
            if op=='<': return php_num(a)<php_num(b) if (isinstance(a,(int,float)) or isinstance(b,(int,float))) else php_string(a)<php_string(b)
            if op=='>': return php_num(a)>php_num(b) if (isinstance(a,(int,float)) or isinstance(b,(int,float))) else php_string(a)>php_string(b)
            if op=='<=': return not self.apply_op('>',a,b)
            if op=='>=': return not self.apply_op('<',a,b)
            if op=='&': return php_int(a)&php_int(b)
            if op=='|': return php_int(a)|php_int(b)
            if op=='^': return php_int(a)^php_int(b)
            if op=='<<': return php_int(a)<<php_int(b)
            if op=='>>': return php_int(a)>>php_int(b)
            if op=='xor': return php_truth(a) ^ php_truth(b)
        except Exception as e:
            raise PhpFatal(str(e))
        return None

class UserFunction:
    def __init__(self, params, defaults, body): self.params=params; self.defaults=defaults; self.body=body

class Interpreter:
    def __init__(self, argv=None, script_name='Command line code'):
