            tok=self.peek(); op=tok.val
            if op=='?':
                prec=1
                if prec<minp: break
                self.pop()
                if self.match(':'):
                    if php_truth(left):
                        # PHP elvis: a ?: b returns a
                        right_true=left
                    else:
                        right_true=self.expr(0)
                    left=right_true
                else:
                    mid=self.expr(0); self.expect(':'); right=self.expr(0)
                    left=mid if php_truth(left) else right
                continue
            if op not in self.PRECEDENCE: break
            prec=self.PRECEDENCE[op]
            if prec<minp: break
            self.pop()
            if op in ('&&','and'):
                if not php_truth(left):
                    _=self.expr(prec+(0 if op in self.RIGHT else 1)); left=False
                else: left=php_truth(self.expr(prec+1));
                continue
            if op in ('||','or'):
                if php_truth(left):
                    _=self.expr(prec+1); left=True
                else: left=php_truth(self.expr(prec+1))
                continue
            if op=='??':
                right=self.expr(prec)
                left = left if left is not None else right
                continue
            right=self.expr(prec + (0 if op in self.RIGHT else 1))
            left=self.apply_op(op,left,right)
        return left
    def prefix(self):
        tok=self.pop(); val=tok.val
        if val in ('+','-','!','~'):
            v=self.expr(13)
            if val=='+': return +php_num(v)
            if val=='-': return -php_num(v)
            if val=='!': return not php_truth(v)
            return ~php_int(v)
        if val in ('++','--'):
            lv=self.parse_lvalue_from_token(self.pop())
            cur=lv.get(True); new=php_num(cur)+(1 if val=='++' else -1); new=int(new) if isinstance(new,float) and new.is_integer() else new
            lv.set(new); return new
        if tok.typ=='NUMBER':
            s=val.replace('_','')
            try:
                if s.lower().startswith('0x'): v=int(s,16)
                elif s.lower().startswith('0b'): v=int(s,2)
                elif any(c in s for c in '.eE'): v=float(s)
                else: v=int(s,10)
            except: v=0
            return self.postfix(v)
        if tok.typ in ('STRING_S','STRING_D'):
            v=tok.val if tok.typ=='STRING_S' else self.I.interpolate(tok.val)
            return self.postfix(v)
        if tok.typ=='VAR':
            lv=self.parse_lvalue_from_token(tok)
            v=lv.get(False)
            return self.postfix(v, lv)
        if tok.typ=='ID':
            low=val.lower()
            if low=='true': return True
            if low=='false': return False
            if low=='null': return None
            if low=='array':
                self.expect('('); arr=self.parse_array(')'); return self.postfix(arr)
            if low=='isset':
                self.expect('('); res=True
                first=True
                while not self.match(')'):
                    if not first: self.expect(',')
                    first=False
                    if self.peek().typ=='VAR':
                        lv=self.parse_lvalue_from_token(self.pop(), quiet_index=True); res = res and lv.isset()
                    else:
                        res = res and (self.expr(0) is not None)
                return res
            if low=='empty':
                self.expect('(')
                if self.peek().typ=='VAR': v=self.parse_lvalue_from_token(self.pop(), quiet_index=True).get(True)
                else: v=self.expr(0)
                self.expect(')'); return not php_truth(v)
            if low=='new':
                cls='stdClass'
                if self.peek().typ=='ID': cls=self.pop().val
                if self.match('('): self.skip_balanced(')')
                return PhpObject(cls)
            if self.match('('):
                args=self.parse_args_after_open()
                return self.postfix(self.I.call_function(val,args))
            const=self.I.get_constant(val)
            if const is None:
                raise PhpFatal(f'Undefined constant "{val}"')
            return self.postfix(const)
        if val=='(':
            v=self.expr(0); self.expect(')'); return self.postfix(v)
        if val=='[':
            arr=self.parse_array(']'); return self.postfix(arr)
        raise PhpParse(f"unexpected token {val!r}")
    def postfix(self, v, lv=None):
        while True:
            if self.match('['):
                if self.match(']'): key=None
                else: key=self.expr(0); self.expect(']')
                if isinstance(v, PhpArray): v=v.get(key)
                elif isinstance(v, str):
                    try: v=v[php_int(key)]
                    except: v=''
                else: v=None
                lv=None
                continue
            if self.match('->'):
                prop=self.pop().val if self.peek().typ in ('ID','VAR') else ''
                if isinstance(v,PhpObject):
                    if self.match('('): self.skip_balanced(')'); v=None
                    else: v=v.props.get(prop)
                else: v=None
                continue
            if self.peek().val in ('++','--'):
                op=self.pop().val
                old=v
                if lv is not None:
                    new=php_num(old)+(1 if op=='++' else -1); new=int(new) if isinstance(new,float) and new.is_integer() else new
                    lv.set(new)
                return old
            break
        return v
    def parse_lvalue_from_token(self,tok, quiet_index=False):
        name=tok.val[1:]
        if name.startswith('{') and name.endswith('}'): name=name[1:-1]
        idx=[]
        while self.match('['):
            if self.match(']'): key=None
            else: key=self.expr(0); self.expect(']')
            idx.append(key)
        return LValue(self.I,name,idx)
    def parse_args_after_open(self):
        args=[]
        if self.match(')'): return args
        while True:
            args.append(self.expr(0))
            if self.match(')'): break
            self.expect(',')
        return args
    def parse_array(self,end):
        arr=PhpArray()
        if self.match(end): return arr
        while True:
            if self.match(end): break
            first=self.expr(0)
            if self.match('=>'):
                val=self.expr(0); arr.set(first,val)
            else:
                arr.append(first)
            if self.match(end): break
            self.expect(',')
        return arr
    def skip_balanced(self,end):
        depth=1
        while self.p<len(self.t) and depth>0:
            tok=self.pop()
            if tok.val in ('(','[','{'): depth+=1
            elif tok.val==end: depth-=1
    def apply_op(self,op,a,b):
        try:
            if op=='+':
                if isinstance(a,PhpArray) and isinstance(b,PhpArray):
                    r=a.copy()
                    for k,v in b.items():
                        if k not in r.data: r.set(k,v)
                    return r
                x,y=php_num(a),php_num(b); z=x+y; return int(z) if isinstance(z,float) and z.is_integer() else z
            if op=='-': z=php_num(a)-php_num(b); return int(z) if isinstance(z,float) and z.is_integer() else z
            if op=='*': z=php_num(a)*php_num(b); return int(z) if isinstance(z,float) and z.is_integer() else z
            if op=='/': return php_num(a)/php_num(b)
            if op=='%': return php_int(a)%php_int(b)
            if op=='**': return php_num(a)**php_num(b)
            if op=='.': return php_string(a)+php_string(b)
            if op=='==': return loose_eq(a,b)
            if op=='!=': return not loose_eq(a,b)
            if op=='===': return strict_eq(a,b)
            if op=='!==': return not strict_eq(a,b)
            if op=='<': return php_num(a)<php_num(b) if (isinstance(a,(int,float)) or isinstance(b,(int,float))) else php_string(a)<php_string(b)
            if op=='>': return php_num(a)>php_num(b) if (isinstance(a,(int,float)) or isinstance(b,(int,float))) else php_string(a)>php_string(b)
            if op=='<=': return not self.apply_op('>',a,b)
            if op=='>=': return not self.apply_op('<',a,b)
            if op=='&': return php_int(a)&php_int(b)
            if op=='|': return php_int(a)|php_int(b)
            if op=='^': return php_int(a)^php_int(b)
            if op=='<<': return php_int(a)<<php_int(b)
            if op=='>>': return php_int(a)>>php_int(b)
            if op=='xor': return php_truth(a) ^ php_truth(b)
        except Exception as e:
            raise PhpFatal(str(e))
        return None

class UserFunction:
    def __init__(self, params, defaults, body): self.params=params; self.defaults=defaults; self.body=body

class Interpreter:
    def __init__(self, argv=None, script_name='Command line code'):
