            'PHP_VERSION': VERSION, 'PHP_MAJOR_VERSION':8, 'PHP_MINOR_VERSION':6, 'PHP_RELEASE_VERSION':0,
            'PHP_EOL':'\n', 'PHP_OS':'Linux', 'PHP_SAPI':'cli', 'STDIN':None,'STDOUT':None,'STDERR':None,
            'DIRECTORY_SEPARATOR':'/', 'PATH_SEPARATOR':':', 'PHP_INT_SIZE':8, 'PHP_INT_MAX':9223372036854775807,
            'true':True,'false':False,'null':None,
        }
        self.functions={}
        self.output=[]
        self.exit_code=0
        self.script_name=script_name
        if argv is None: argv=[]
        a=PhpArray([(i,x) for i,x in enumerate(argv)])
        self.vars['argv']=a; self.vars['argc']=len(argv)
        srv=PhpArray()
        for k,v in os.environ.items(): srv.set(k,v)
        srv.set('argv', a); srv.set('argc', len(argv)); srv.set('PHP_SELF', argv[0] if argv else '')
        srv.set('SCRIPT_NAME', argv[0] if argv else '')
        srv.set('SCRIPT_FILENAME', argv[0] if argv and argv[0] != 'Standard input code' else '')
