        self.vars['_GET']=PhpArray(); self.vars['_POST']=PhpArray(); self.vars['_COOKIE']=PhpArray(); self.vars['_FILES']=PhpArray(); self.vars['_REQUEST']=PhpArray()
    def write(self,s): self.output.append(str(s))
    def flush(self):
        sys.stdout.write(''.join(self.output)); self.output=[]
    def warning(self,msg): self.write(f"\nWarning: {msg} in {self.script_name} on line 1\n")
    def fatal(self,msg):
