    mp={'Y':dt.strftime('%Y'),'y':dt.strftime('%y'),'m':dt.strftime('%m'),'n':str(dt.month),'d':dt.strftime('%d'),'j':str(dt.day),'H':dt.strftime('%H'),'G':str(dt.hour),'i':dt.strftime('%M'),'s':dt.strftime('%S'),'U':str(int(ts)),'M':dt.strftime('%b'),'F':dt.strftime('%B'),'D':dt.strftime('%a'),'l':dt.strftime('%A')}
