def modules_text():
    return "[PHP Modules]\n" + "\n".join(MODULES) + "\n\n[Zend Modules]\nZend OPcache\n"

def ini_text():
    return 'Configuration File (php.ini) Path: "/usr/local/lib"\nLoaded Configuration File:         (none)\nScan for additional .ini files in: (none)\nAdditional .ini files parsed:      (none)\n'

def inidiff_text():
