def reflection_function(name):
    sigs={'strlen':('Core','string $string','int'),'count':('standard','Countable|array $value, int $mode = COUNT_NORMAL','int'),'json_encode':('json','mixed $value, int $flags = 0, int $depth = 512','string|false'),'var_dump':('Core','mixed $value, mixed ...$values','void')}
    if name not in sigs: return None
    ext,param,ret=sigs[name]
    params=[p.strip() for p in param.split(',') if p.strip()]
    s=f"Function [ <internal:{ext}> function {name} ] {{\n\n  - Parameters [{len(params)}] {{\n"
    for i,p in enumerate(params): s+=f"    Parameter #{i} [ <required> {p} ]\n"
    s+=f"  }}\n  - Return [ {ret} ]\n}}\n"
    return s

def reflection_class(name):
    if name.lower()=='stdclass':
        return "Class [ <internal:Core> class stdClass ] {\n\n  - Constants [0] {\n  }\n\n  - Static properties [0] {\n  }\n\n  - Static methods [0] {\n  }\n\n  - Properties [0] {\n  }\n\n  - Methods [0] {\n  }\n}\n"
    return None

def strip_php(src):
    # Lightweight equivalent for -w: remove comments and collapse whitespace inside PHP sections.
    def strip_code(code):
        code=re.sub(r'/\*.*?\*/',' ',code,flags=re.S)
        code=re.sub(r'//.*?(?=\n|$)',' ',code)
        code=re.sub(r'#.*?(?=\n|$)',' ',code)
        code=re.sub(r'\s+',' ',code).strip()
        return (' '+code+' ') if code else ''
    out=''; pos=0
    while True:
        m=re.search(r'<\?(?:php|=)?',src[pos:],re.I)
        if not m: out+=src[pos:]; break
        s=pos+m.start(); e=pos+m.end(); out+=src[pos:e]
        close=src.find('?>',e)
        if close<0: out+=strip_code(src[e:]); break
        out+=strip_code(src[e:close])+'?>'; pos=close+2
    return out

