def parse_cli(argv):
    opts={'ini_defs':[]}; rest=[]; i=0
    while i<len(argv):
        a=argv[i]
        if a=='--': rest=argv[i+1:]; break
        if a in ('-h','--help','-?'): opts['help']=True; i+=1; continue
        if a in ('-v','--version'): opts['version']=True; i+=1; continue
        if a=='-m': opts['modules']=True; i+=1; continue
        if a=='-i': opts['info']=True; i+=1; continue
        if a=='--ini': opts['ini']=True; i+=1; continue
        if a=='--ini=diff': opts['inidiff']=True; i+=1; continue
        if a in ('--rf','--rc','--re','--rz','--ri'):
            if i+1>=len(argv): opts['arg_error']=(i+1,a[-1],f"no argument for option {a}"); break
            opts[a[2:]]=argv[i+1]; i+=2; continue
        if a in ('-r','-f','-B','-R','-F','-E','-c','-d','-S','-t','--repeat'):
            if i+1>=len(argv): opts['missing']=a; break
            key={'-r':'run','-f':'file','-B':'begin','-R':'line','-F':'linefile','-E':'end','-c':'config','-d':'define','-S':'server','-t':'docroot','--repeat':'repeat'}[a]
