    if 'server' in opts:
        sys.stderr.write(f"[Thu Jan  1 00:00:00 1970] PHP {VERSION} Development Server (http://{opts['server']}) started\n"); return 0
    try:
        if opts.get('lint') or opts.get('strip') or opts.get('highlight'):
            path=opts['args'][0] if opts.get('args') else opts.get('file')
            if not path:
                sys.stdout.write(HELP); sys.stderr.write("Error in argument 1, char 2: no argument for option f\n"); return 1
