            if opts.get('highlight'): sys.stdout.write(highlight_php(data)); return 0
        if 'line' in opts or 'linefile' in opts:
            args=['Standard input code']+opts.get('args',[])
            I=Interpreter(args,'Command line run code')
            if 'begin' in opts: I.exec_code(opts['begin'])
