            if 'end' in opts: I.exec_code(opts['end'])
            I.flush(); return 0
        if 'run' in opts:
            args=['Standard input code']+opts.get('args',[])
            I=Interpreter(args,'Command line code')
            I.exec_code(opts['run']); I.flush(); return I.exit_code
        path=opts.get('file') or (opts['args'][0] if opts.get('args') else None)
        if path:
            script_args=[path]+(opts.get('args',[])[1:] if not opts.get('file') else opts.get('args',[]))
