        if I: I.flush()
        return e.code
    except Exception as e:
        I=locals().get('I',None)
        if I:
            try: I.fatal(str(e))
            except ExitExc: pass
            I.flush()
        else: sys.stdout.write(f"\nFatal error: {e}\n")
        return 255

